def rle(s: str) -> str:
    """Return the run-length encoding of s, as described in SPEC.md."""
    out = []
    prev, count = None, 0
    for ch in s:
        if ch == prev:
            count += 1
        else:
            if prev is not None:
                out.append(prev + str(count))
            prev, count = ch, 1
    if prev is not None:
        out.append(prev + str(count))
    return "".join(out)

